{
  "name": "Telnet 连接接口",
  "name_en": "Telnet Connection Interface",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于通过 Telnet 协议连接远程主机。在实验系统中可用于建立会话、发送文本命令、读取返回数据、处理 Telnet 选项协商，以及进行交互式远程控制。",
  "description_en": "This is a non-physical software communication component for connecting to remote hosts over the Telnet protocol. In laboratory systems, it can be used to open sessions, send text commands, read returned data, handle Telnet option negotiation, and support interactive remote control.",
  "tag_hints": [
    "telnet communication",
    "remote command session",
    "network socket I/O",
    "text protocol exchange",
    "interactive terminal session",
    "option negotiation"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开到远程 Telnet 主机的连接。",
      "description_en": "Open a connection to a remote Telnet host."
    },
    {
      "action_name": "auto-msg",
      "description": "输出调试消息。",
      "description_en": "Output a debug message."
    },
    {
      "action_name": "auto-set_debuglevel",
      "description": "设置调试输出级别。",
      "description_en": "Set the debug output level."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 Telnet 连接。",
      "description_en": "Close the Telnet connection."
    },
    {
      "action_name": "auto-get_socket",
      "description": "获取内部使用的套接字对象。",
      "description_en": "Get the internally used socket object."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取内部套接字的文件描述符。",
      "description_en": "Get the file descriptor of the internal socket."
    },
    {
      "action_name": "auto-write",
      "description": "向 Telnet 连接写入数据。",
      "description_en": "Write data to the Telnet connection."
    },
    {
      "action_name": "auto-read_until",
      "description": "读取数据直到出现指定内容或超时。",
      "description_en": "Read data until the specified content is found or a timeout occurs."
    },
    {
      "action_name": "auto-read_all",
      "description": "持续读取全部数据直到连接结束。",
      "description_en": "Read all data until the connection reaches EOF."
    },
    {
      "action_name": "auto-read_some",
      "description": "读取至少一部分可用数据。",
      "description_en": "Read at least some available data."
    },
    {
      "action_name": "auto-read_very_eager",
      "description": "以尽量不阻塞的方式读取当前可立即获得的全部数据。",
      "description_en": "Read all immediately available data with minimal blocking."
    },
    {
      "action_name": "auto-read_eager",
      "description": "读取当前已准备好的数据。",
      "description_en": "Read data that is currently ready and available."
    },
    {
      "action_name": "auto-read_lazy",
      "description": "处理并返回队列中已存在的数据，不主动进行新的套接字读取。",
      "description_en": "Process and return data already in the queues without initiating new socket I/O."
    },
    {
      "action_name": "auto-read_very_lazy",
      "description": "返回已处理队列中当前可用的数据，不进行套接字 I/O。",
      "description_en": "Return currently available cooked-queue data without socket I/O."
    },
    {
      "action_name": "auto-read_sb_data",
      "description": "读取 Telnet 子协商区段中的可用数据。",
      "description_en": "Read available data from the Telnet subnegotiation buffer."
    },
    {
      "action_name": "auto-set_option_negotiation_callback",
      "description": "设置 Telnet 选项协商回调函数。",
      "description_en": "Set the callback function for Telnet option negotiation."
    },
    {
      "action_name": "auto-process_rawq",
      "description": "处理原始输入队列并转换为可用数据队列。",
      "description_en": "Process the raw input queue and convert it into usable data queues."
    },
    {
      "action_name": "auto-rawq_getchar",
      "description": "从原始输入队列获取下一个字符。",
      "description_en": "Get the next character from the raw input queue."
    },
    {
      "action_name": "auto-fill_rawq",
      "description": "通过一次套接字接收操作填充原始输入队列。",
      "description_en": "Fill the raw input queue using one socket receive operation."
    },
    {
      "action_name": "auto-sock_avail",
      "description": "检查套接字上是否有可用数据。",
      "description_en": "Check whether data is available on the socket."
    },
    {
      "action_name": "auto-interact",
      "description": "启动交互式 Telnet 会话。",
      "description_en": "Start an interactive Telnet session."
    },
    {
      "action_name": "auto-mt_interact",
      "description": "以多线程方式启动交互式 Telnet 会话。",
      "description_en": "Start an interactive Telnet session in multithreaded mode."
    },
    {
      "action_name": "auto-listener",
      "description": "运行多线程交互会话中使用的监听辅助流程。",
      "description_en": "Run the listener helper used in the multithreaded interactive session."
    },
    {
      "action_name": "auto-expect",
      "description": "读取数据直到匹配给定正则表达式列表中的某一项或超时。",
      "description_en": "Read data until one of the given regular expressions matches or a timeout occurs."
    }
  ]
}

